// ============================================================================
// D_PHY_apb: APB4 register wrapper around D_PHY_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/D_PHY.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/D_PHY.md
// ============================================================================
module D_PHY_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic d_lp_p,
  output logic d_lp_n,
  output logic d_hs_p,
  output logic d_hs_n,
  output logic d_hs_en,
  output logic c_lp_p,
  output logic c_lp_n,
  output logic c_hs_p,
  output logic c_hs_n,
  output logic c_hs_en,
  input logic r_lp_p,
  input logic r_lp_n,
  input logic r_hs_p,
  input logic r_hs_n,
  input logic r_hs_en
);
  localparam logic [31:0] ID_VALUE = 32'h44500200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [11:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd12) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_irq;
  logic          c_irq_clear;
  logic          c_hs_req;
  logic [7:0]    c_hs_tx_data;
  logic          c_hs_tx_valid;
  logic          c_hs_tx_ready;
  logic          c_hs_tx_done;
  logic          c_esc_req;
  logic [7:0]    c_esc_cmd;
  logic          c_esc_release;
  logic [7:0]    c_lpdt_data;
  logic          c_lpdt_valid;
  logic          c_lpdt_last;
  logic          c_lpdt_ready;
  logic          c_esc_done;
  logic          c_rx_hs_active;
  logic [7:0]    c_rx_data;
  logic          c_rx_data_valid;
  logic [7:0]    c_rx_esc_cmd;
  logic          c_rx_esc_valid;
  logic          c_rx_ulps;
  D_PHY_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .irq(c_irq),
    .irq_clear(c_irq_clear),
    .hs_req(c_hs_req),
    .hs_tx_data(c_hs_tx_data),
    .hs_tx_valid(c_hs_tx_valid),
    .hs_tx_ready(c_hs_tx_ready),
    .hs_tx_done(c_hs_tx_done),
    .esc_req(c_esc_req),
    .esc_cmd(c_esc_cmd),
    .esc_release(c_esc_release),
    .lpdt_data(c_lpdt_data),
    .lpdt_valid(c_lpdt_valid),
    .lpdt_last(c_lpdt_last),
    .lpdt_ready(c_lpdt_ready),
    .esc_done(c_esc_done),
    .d_lp_p(d_lp_p),
    .d_lp_n(d_lp_n),
    .d_hs_p(d_hs_p),
    .d_hs_n(d_hs_n),
    .d_hs_en(d_hs_en),
    .c_lp_p(c_lp_p),
    .c_lp_n(c_lp_n),
    .c_hs_p(c_hs_p),
    .c_hs_n(c_hs_n),
    .c_hs_en(c_hs_en),
    .r_lp_p(r_lp_p),
    .r_lp_n(r_lp_n),
    .r_hs_p(r_hs_p),
    .r_hs_n(r_hs_n),
    .r_hs_en(r_hs_en),
    .rx_hs_active(c_rx_hs_active),
    .rx_data(c_rx_data),
    .rx_data_valid(c_rx_data_valid),
    .rx_esc_cmd(c_rx_esc_cmd),
    .rx_esc_valid(c_rx_esc_valid),
    .rx_ulps(c_rx_ulps)
  );

  // ---------------- registers ----------------
  logic [10:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [3:0] p_CMD;   // 12'h014 CMD (pulses)
  logic [7:0] r_ESC;   // 12'h018 ESC
  logic [7:0] h_HS_TX;   // 12'h01C HS_TX holding register
  logic [8:0] h_LPDT;   // 12'h020 LPDT holding register
  logic [7:0] h_RX;   // 12'h024 RX holding register
  logic [7:0] h_RX_ESC;   // 12'h028 RX_ESC holding register
  logic full_HS_TX;
  logic full_LPDT;
  logic avail_RX;
  logic avail_RX_ESC;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      p_CMD <= '0;
      r_ESC <= 8'h0;
      h_HS_TX <= '0;
      h_LPDT <= '0;
      h_RX <= '0;
      h_RX_ESC <= '0;
      full_HS_TX <= 1'b0;
      full_LPDT <= 1'b0;
      avail_RX <= 1'b0;
      avail_RX_ESC <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[10:0] & wmask[10:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      p_CMD <= (wr && hit[5]) ? PWDATA[3:0] & wmask[3:0] : '0;
      if (wr && hit[6]) r_ESC <= (r_ESC & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[7] && !full_HS_TX) h_HS_TX <= (h_HS_TX & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[7] && !full_HS_TX) full_HS_TX <= 1'b1;
      else if (full_HS_TX && c_hs_tx_ready) full_HS_TX <= 1'b0;
      if (wr && hit[8] && !full_LPDT) h_LPDT <= (h_LPDT & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[8] && !full_LPDT) full_LPDT <= 1'b1;
      else if (full_LPDT && c_lpdt_ready) full_LPDT <= 1'b0;
      if (c_rx_data_valid && (!avail_RX || (rd && hit[9]))) begin
        h_RX[7:0] <= c_rx_data[7:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[9]) avail_RX <= 1'b0;
      if (c_rx_esc_valid && (!avail_RX_ESC || (rd && hit[10]))) begin
        h_RX_ESC[7:0] <= c_rx_esc_cmd[7:0];
        avail_RX_ESC <= 1'b1;
      end else if (rd && hit[10]) avail_RX_ESC <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_hs_req = p_CMD[0:0];
  assign c_esc_req = p_CMD[1:1];
  assign c_esc_release = p_CMD[2:2];
  assign c_irq_clear = p_CMD[3:3];
  assign c_esc_cmd = r_ESC[7:0];
  assign c_hs_tx_data[7:0] = h_HS_TX[7:0];
  assign c_lpdt_data[7:0] = h_LPDT[7:0];
  assign c_lpdt_last = h_LPDT[8:8];
  assign c_hs_tx_valid = full_HS_TX;
  assign c_lpdt_valid = full_LPDT;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_hs_tx_done;
    irq_set[1] = c_esc_done;
    irq_set[2] = c_irq;
    irq_set[3] = full_HS_TX & c_hs_tx_ready;
    irq_set[4] = wr & (hit[7]) & full_HS_TX;
    irq_set[5] = full_LPDT & c_lpdt_ready;
    irq_set[6] = wr & (hit[8]) & full_LPDT;
    irq_set[7] = c_rx_data_valid & (~avail_RX | (rd & hit[9]));
    irq_set[8] = c_rx_data_valid & avail_RX & ~(rd & hit[9]);
    irq_set[9] = c_rx_esc_valid & (~avail_RX_ESC | (rd & hit[10]));
    irq_set[10] = c_rx_esc_valid & avail_RX_ESC & ~(rd & hit[10]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [3:0] flags = {avail_RX_ESC, avail_RX, full_LPDT, full_HS_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd6: apb_rdata = 32'(r_ESC);
      10'd7: apb_rdata = 32'(h_HS_TX);
      10'd8: apb_rdata = 32'(h_LPDT);
      10'd9: apb_rdata = 32'(h_RX);
      10'd10: apb_rdata = 32'(h_RX_ESC);
      10'd11: apb_rdata = 32'({c_rx_ulps, c_rx_hs_active});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
